def check(candidate) -> bool:
    try:
        N = 2000
        K = 8
        if not isinstance(candidate, list):
            return False
        if len(candidate) > N + 1:
            return False
        for x in candidate:
            if isinstance(x, bool) or not isinstance(x, int):
                return False
            if x < 0 or x > N:
                return False
        if len(set(candidate)) != len(candidate):
            return False
        A = sorted(candidate)
        cnt = [0] * (N + 1)
        L = len(A)
        for i in range(L):
            a = A[i]
            for j in range(i, L):
                s = a + A[j]
                if s > N:
                    break
                if i == j:
                    cnt[s] += 1
                else:
                    cnt[s] += 2
                if cnt[s] > K:
                    return False
        for n in range(N + 1):
            if cnt[n] < 1 or cnt[n] > K:
                return False
        return True
    except Exception:
        return False
